        c_reg = __builtin_amdgcn_mfma_scale_f32_32x32x64_f8f6f4(
            a_reg, b_reg, c_reg,
            4, 4,       // Atype=FP4, Btype=FP4
            0, sa,      // OPSEL_A=0, scale_a
            0, sb       // OPSEL_B=0, scale_b
        );
    }

    // ─── Epilogue: write 16 f32 results per thread as bf16 ──────
    // Output layout matches AMD blog: c_reg maps to specific (row,col) positions
    for (int i = 0; i < 4; i++) {
        int base_row = bm + (tid / 32) * 4 + i;
        if (base_row >= M) continue;

        for (int j = 0; j < 4; j++) {
            int col = bn + (tid % 32);
            // Map c_reg indices to output positions
            // c_reg layout: 4 groups of 4, interleaved with wavefront halves
            int out_row = bm + (tid % 32);  // not right...
            // Actually use the blog's exact output mapping:
        }
    }

    // Use the exact output mapping from the AMD blog:
    // C[threadIdx.x % 32 + (threadIdx.x / 32) * 4 * 32 + i * 32 * 8]
    for (int i = 0; i < 4; i++) {
        int r0 = (tid / 32) * 4 + i * 8;
        for (int j = 0; j < 4; j++) {
            int row = bm + r0 + j;
            int col = bn + (tid % 32);
            if (row < M && col < N) {
                C[row * N + col] = __float2bfloat16(c_reg[i * 4 + j]);
            }
        }
    }
}

