    tree.record_attempt(c.id, "# shared reuse v1\n...", 0.60)
    tree.record_attempt(c.id, "# shared reuse v2\n...", 0.35)

    # Divergence: c's latest score dropped well below its best (0.35 < 0.8 * 0.60)
    if tree.check_divergence(c, 0.35):
