#!POPCORN leaderboard amd-mxfp4-mm
#!POPCORN gpu MI355X

"""MXFP4 GEMM with hardware MFMA intrinsic on gfx950.

Uses __builtin_amdgcn_mfma_scale_f32_32x32x64_f8f6f4 (CDNA4 only).
Single hardware instruction does dequant+matmul for FP4, replacing scalar LUT.

1 wavefront (64 threads) per 32x32 tile. Per-thread E8M0 scales.
Source: https://rocm.blogs.amd.com/software-tools-optimization/matrix-cores-cdna/README.html
"""

import os
os.environ["PYTORCH_ROCM_ARCH"] = "gfx950"
os.environ["CXX"] = "clang++"

import torch
from torch.utils.cpp_extension import load_inline
from aiter import dtypes
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from task import input_t, output_t

HIP_SOURCE = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

using fp4x2_t = uint8_t;
typedef fp4x2_t fp4x64_t __attribute__((ext_vector_type(32)));
typedef float fp32x16_t __attribute__((ext_vector_type(16)));

#define TILE_M 32
#define TILE_N 32
#define TILE_K 64
#define TILE_K_BYTES 32
#define WAVESIZE 64

__global__ void mxfp4_gemm_mfma(
    const uint8_t* __restrict__ A,   // [M, K/2]
    const uint8_t* __restrict__ B,   // [N, K/2]
    const uint8_t* __restrict__ As,  // [M, K/32]
    const uint8_t* __restrict__ Bs,  // [N, K/32]
    at::BFloat16* __restrict__ C,
    int M, int N, int K
) {
    int bm = blockIdx.y * TILE_M;
    int bn = blockIdx.x * TILE_N;
    int tid = threadIdx.x;

    int K_half = K / 2;
    int K_scale = K / 32;
    int num_k_tiles = K / TILE_K;

    fp32x16_t c_reg = {};
    for (int i = 0; i < 16; i++) c_reg[i] = 0.0f;

    for (int kt = 0; kt < num_k_tiles; kt++) {
        fp4x64_t a_reg = {};
        fp4x64_t b_reg = {};

        // Load A: thread t reads row (t%32), K-half (t/32)
        int a_row = bm + (tid % 32);
        int a_k_start = kt * TILE_K_BYTES + (tid / 32) * 16;
        if (a_row < M) {
            const uint8_t* ap = A + a_row * K_half + a_k_start;
            for (int i = 0; i < 16; i++) a_reg[i] = ap[i];
        }

        // Load B: threads 0-31 handle B rows bn+0..bn+15,
        //         threads 32-63 handle B rows bn+16..bn+31
        int b_row_base = bn + 16 * (tid / 32);
        int b_byte_col = (tid % 32) / 2;
        int b_nibble = tid % 2;
        int b_k_off = kt * TILE_K_BYTES;

        for (int i = 0; i < 16; i++) {
            int br = b_row_base + i;
            if (br >= N) { b_reg[i] = 0; continue; }
            uint8_t by0 = B[br * K_half + b_k_off + b_byte_col * 2];
            uint8_t by1 = B[br * K_half + b_k_off + b_byte_col * 2 + 1];
            uint8_t v0 = b_nibble ? ((by0 >> 4) & 0xF) : (by0 & 0xF);
            uint8_t v1 = b_nibble ? ((by1 >> 4) & 0xF) : (by1 & 0xF);
            b_reg[i] = v0 | (v1 << 4);
        }

        // Scales
        int sg = kt * 2 + (tid / 32);
        uint8_t sa = (a_row < M && sg < K_scale) ? As[a_row * K_scale + sg] : 127;
        int brep = b_row_base;
        uint8_t sb = (brep < N && sg < K_scale) ? Bs[brep * K_scale + sg] : 127;

        c_reg = __builtin_amdgcn_mfma_scale_f32_32x32x64_f8f6f4(
            a_reg, b_reg, c_reg, 4, 4, 0, sa, 0, sb);
    }

    // Write output
    int out_col = bn + (tid % 32);
    if (out_col < N) {
        for (int i = 0; i < 4; i++) {
            int rb = bm + (tid / 32) * 4 + i * 8;
            for (int j = 0; j < 4; j++) {
                int row = rb + j;
                if (row < M) C[row * N + out_col] = __float2bfloat16(c_reg[i * 4 + j]);
            }
        }
    }
}

torch::Tensor launch(torch::Tensor A, torch::Tensor B,
                     torch::Tensor As, torch::Tensor Bs,
                     int M, int N, int K) {
    auto C = torch::empty({M, N}, torch::TensorOptions()
        .dtype(torch::kBFloat16).device(A.device()));
    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);
    mxfp4_gemm_mfma<<<grid, WAVESIZE, 0, at::cuda::getCurrentCUDAStream()>>>(
        A.data_ptr<uint8_t>(), B.data_ptr<uint8_t>(),
        As.data_ptr<uint8_t>(), Bs.data_ptr<uint8_t>(),
        reinterpret_cast<at::BFloat16*>(C.data_ptr()), M, N, K);
    return C;
}
"""

CPP_SOURCE = "torch::Tensor launch(torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, int, int, int);"

try:
    _mod = load_inline(
        name="mfma_gemm_v5", cpp_sources=[CPP_SOURCE], cuda_sources=[HIP_SOURCE],
        functions=["launch"], verbose=False,
        extra_cuda_cflags=["--offload-arch=gfx950", "-std=c++20", "-O3"],
    )
    _OK = True
except Exception as e:
    print(f"[mfma] {e}")
    _OK = False


def custom_kernel(data: input_t) -> output_t:
    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]
    ks = K // 32

    if not _OK:
        import aiter
        Aq, Asc = dynamic_mxfp4_quant(A.contiguous())
        Ash = e8m0_shuffle(Asc).view(dtypes.fp8_e8m0)
        return aiter.gemm_a4w4(Aq.view(dtypes.fp4x2), B_shuffle, Ash, B_scale_sh,
                               dtype=dtypes.bf16, bpreshuffle=True)

    Aq, Asc = dynamic_mxfp4_quant(A.contiguous())
    A_bytes = Aq.view(torch.uint8)
    As_bytes = Asc[:M, :ks].contiguous().view(torch.uint8)
    B_bytes = B_q.view(torch.uint8)
    _, Bsc = dynamic_mxfp4_quant(B.contiguous())
    Bs_bytes = Bsc[:N, :ks].contiguous().view(torch.uint8)

    return _mod.launch(A_bytes, B_bytes, As_bytes, Bs_bytes, M, N, K)

