#!POPCORN leaderboard amd-mxfp4-mm
#!POPCORN gpu MI355X

"""Split-K GEMM: Parallelize K dimension for small-M shapes.

For M=16 K=7168: standard aiter uses ~20.9µs because few M-tiles means low CU occupancy.
Split-K launches K_SPLITS blocks per output tile, each processing K/K_SPLITS elements,
then atomicAdd partial results.

Strategy:
- M<=16: use split-K custom kernel (4 K-splits)
- M>16: use aiter (it's already fast for large M)
"""

import os
os.environ["PYTORCH_ROCM_ARCH"] = "gfx950"
os.environ["CXX"] = "clang++"

import torch
from torch.utils.cpp_extension import load_inline
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from task import input_t, output_t

HIP_SOURCE = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

typedef int a_reg_t __attribute__((ext_vector_type(8)));
typedef int b_reg_t __attribute__((ext_vector_type(8)));
typedef float c_reg_t __attribute__((ext_vector_type(16)));

#define TILE_M 32
#define TILE_N 32
#define TILE_K 64
#define TILE_K_BYTES 32
#define WAVESIZE 64

// Split-K kernel: each block handles a SLICE of K, atomicAdd partial results
__global__ __launch_bounds__(WAVESIZE, 8)
void mxfp4_gemm_splitk(
    const uint8_t* __restrict__ A,
    const uint8_t* __restrict__ B,
    const uint8_t* __restrict__ As,
    const uint8_t* __restrict__ Bs,
    float* __restrict__ C_partial,  // [M, N] float32 for atomic accumulation
    int M, int N, int K,
    int k_start, int k_end  // K range for this split
) {
    const int bm = blockIdx.y * TILE_M;
    const int bn = blockIdx.x * TILE_N;
    const int tid = threadIdx.x;
    const int K_half = K / 2;
    const int K_scale = K / 32;

    // K range for this split (in FP4 elements)
    const int split_k_start = k_start;
    const int split_k_end = k_end;
    const int num_k_tiles = (split_k_end - split_k_start) / TILE_K;

    c_reg_t c_reg = {};
    #pragma unroll
    for (int i = 0; i < 16; i++) c_reg[i] = 0.0f;

    const int lane = tid & 31;
    const int half_id = tid >> 5;
    const int a_row = bm + lane;
    const int b_col = bn + lane;
    const bool a_valid = (a_row < M);
    const bool b_valid = (b_col < N);

    const uint8_t* __restrict__ a_base = A + a_row * K_half;
    const uint8_t* __restrict__ b_base = B + b_col * K_half;
    const uint8_t* __restrict__ as_base = As + a_row * K_scale;
    const uint8_t* __restrict__ bs_base = Bs + b_col * K_scale;

    for (int kt = 0; kt < num_k_tiles; kt++) {
        a_reg_t a_reg = {};
        b_reg_t b_reg = {};

        // Offset into the K slice
        const int abs_kt = (split_k_start / TILE_K) + kt;
        const int k_byte_off = abs_kt * TILE_K_BYTES + half_id * 16;

        if (a_valid && k_byte_off + 16 <= K_half) {
            uint8_t* a_bytes = reinterpret_cast<uint8_t*>(&a_reg);
            const uint8_t* a_ptr = a_base + k_byte_off;
            #pragma unroll
            for (int i = 0; i < 16; i++) a_bytes[i] = a_ptr[i];
        }
        if (b_valid && k_byte_off + 16 <= K_half) {
            uint8_t* b_bytes = reinterpret_cast<uint8_t*>(&b_reg);
            const uint8_t* b_ptr = b_base + k_byte_off;
            #pragma unroll
            for (int i = 0; i < 16; i++) b_bytes[i] = b_ptr[i];
        }

        const int sg = abs_kt * 2 + half_id;
        const int sa = (a_valid && sg < K_scale) ? (int)as_base[sg] : 127;
        const int sb = (b_valid && sg < K_scale) ? (int)bs_base[sg] : 127;

        c_reg = __builtin_amdgcn_mfma_scale_f32_32x32x64_f8f6f4(
            a_reg, b_reg, c_reg, 4, 4, 0, sa, 0, sb);
    }

    // Atomic accumulate to C_partial (float32)
    const int out_col = bn + lane;
    if (out_col < N) {
        #pragma unroll
        for (int r = 0; r < 16; r++) {
            const int out_row = bm + (r & 3) + (r >> 2) * 8 + half_id * 4;
            if (out_row < M) {
                atomicAdd(&C_partial[out_row * N + out_col], c_reg[r]);
            }
        }
    }
}

// Convert float32 partial to bf16 output
__global__ void convert_f32_to_bf16(
    const float* __restrict__ C_partial,
    __hip_bfloat16* __restrict__ C,
    int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        C[idx] = (__hip_bfloat16)(C_partial[idx]);
    }
}

void launch_splitk(torch::Tensor A, torch::Tensor B,
                   torch::Tensor As, torch::Tensor Bs,
                   torch::Tensor C_partial, torch::Tensor C,
                   int k_splits) {
    int M = A.size(0), K = A.size(1) * 2, N = B.size(0);
    int K_per_split = (K / k_splits / TILE_K) * TILE_K;  // Round down to TILE_K

    dim3 block(WAVESIZE);

    // Launch k_splits kernels sequentially (they all atomicAdd to same buffer)
    // Zero the partial buffer first
    C_partial.zero_();

    for (int s = 0; s < k_splits; s++) {
        int k_start = s * K_per_split;
        int k_end = (s == k_splits - 1) ? K : (s + 1) * K_per_split;
        if (k_start >= K) break;

        dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);
        mxfp4_gemm_splitk<<<grid, block>>>(
            A.data_ptr<uint8_t>(), B.data_ptr<uint8_t>(),
            As.data_ptr<uint8_t>(), Bs.data_ptr<uint8_t>(),
            C_partial.data_ptr<float>(), M, N, K,
            k_start, k_end);
    }

    // Convert to bf16
    int size = M * N;
    convert_f32_to_bf16<<<(size + 255) / 256, 256>>>(
        C_partial.data_ptr<float>(),
        reinterpret_cast<__hip_bfloat16*>(C.data_ptr()), size);
}
"""

CPP_SOURCE = """
void launch_splitk(torch::Tensor A, torch::Tensor B,
                   torch::Tensor As, torch::Tensor Bs,
                   torch::Tensor C_partial, torch::Tensor C,
                   int k_splits);
"""

try:
    _mod = load_inline(
        name="fp4mfma_splitk", cpp_sources=[CPP_SOURCE], cuda_sources=[HIP_SOURCE],
        functions=["launch_splitk"], verbose=False,
        extra_cuda_cflags=["--offload-arch=gfx950", "-std=c++20", "-O3"],
    )
    _OK = True
except Exception as e:
    print(f"[splitk] {e}")
    _OK = False


def e8m0_unshuffle(scale_shuffled, orig_m, orig_n):
    sm, sn = scale_shuffled.shape
    scale = scale_shuffled.view(sm // 32, sn // 8, 4, 16, 2, 2)
    scale = scale.permute(0, 5, 3, 1, 4, 2).contiguous()
    return scale.view(sm, sn)[:orig_m, :orig_n]


_bs_cache: dict = {}
_buf_cache: dict = {}


def custom_kernel(data: input_t) -> output_t:
    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]
    ks = K // 32

    Aq, Asc = dynamic_mxfp4_quant(A.contiguous())

    # Route: split-K for small M, aiter for large M
    if _OK and M <= 16 and K >= 2048:
        A_bytes = Aq.view(torch.uint8)
        As_bytes = Asc[:M, :ks].contiguous().view(torch.uint8)
        B_bytes = B_q.view(torch.uint8)

        bs_key = (id(B_scale_sh), N, ks)
        if bs_key not in _bs_cache:
            _bs_cache.clear()
            _bs_cache[bs_key] = e8m0_unshuffle(
                B_scale_sh.view(torch.uint8), N, ks
            ).contiguous().view(torch.uint8)
        Bs_bytes = _bs_cache[bs_key]

        # Allocate partial buffer (float32) and output (bf16)
        buf_key = (M, N)
        if buf_key not in _buf_cache:
            _buf_cache.clear()
            _buf_cache[buf_key] = (
                torch.zeros((M, N), dtype=torch.float32, device=A.device),
                torch.empty((M, N), dtype=torch.bfloat16, device=A.device),
            )
        C_partial, C = _buf_cache[buf_key]

        # Choose K splits: more splits = more parallelism for small M
        k_splits = 4 if K >= 4096 else 2

        _mod.launch_splitk(A_bytes, B_bytes, As_bytes, Bs_bytes,
                          C_partial, C, k_splits)
        return C
    else:
        # aiter for M>16 (already fast)
        Ash = e8m0_shuffle(Asc).view(dtypes.fp8_e8m0)
        return aiter.gemm_a4w4(
            Aq.view(dtypes.fp4x2), B_shuffle, Ash, B_scale_sh,
            dtype=dtypes.bf16, bpreshuffle=True,
        )

